"""Brute-force solvers for Independent Set and Clique, from the definitions."""

from __future__ import annotations

from itertools import combinations
from typing import Any


def _has_independent_set(n: int, edges: list, k: int) -> bool:
    if k <= 0:
        return True
    if k > n:
        return False
    edge_set = {frozenset((u, v)) for u, v in edges}
    for combo in combinations(range(n), k):
        if all(frozenset((u, v)) not in edge_set for u, v in combinations(combo, 2)):
            return True
    return False


def _has_clique(n: int, edges: list, k: int) -> bool:
    if k <= 0:
        return True
    if k > n:
        return False
    edge_set = {frozenset((u, v)) for u, v in edges}
    for combo in combinations(range(n), k):
        if all(frozenset((u, v)) in edge_set for u, v in combinations(combo, 2)):
            return True
    return False


def solve_independent_set(instance: dict[str, Any]) -> bool:
    return _has_independent_set(instance["n"], instance["edges"], instance["k"])


def solve_clique(instance: dict[str, Any]) -> bool:
    return _has_clique(instance["n"], instance["edges"], instance["k"])
EOF
